import{_ as s,C as t,o as n,c as d,E as o,a2 as c}from"./chunks/framework.BdWD-ld-.js";const l="/joinwell52/assets/mcp-session-boundary-20261118/mcp-argument-path.zh.svg",C=JSON.parse('{"title":"一个参数名，怎么会读到 AI 的会话资料？","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"一个参数名，怎么会读到 AI 的会话资料？","date":"2026-11-18","published_date":"2026-11-18","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"外部 MCP 服务声明参数名，是否就能决定客户端发送哪些会话数据？","summary":"Google ADK 的一次修复揭示：服务端列出一个参数名，旧客户端便可能从会话状态取同名值。我们固定修复前后版本重放，再检查 CodeFlowMu 的对应入口。","cover":"/assets/mcp-session-boundary-20261118/mcp-session-boundary.cover.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"ADK 固定提交类级替身对照；CodeFlowMu V3.0.152 桥接与环境辅助函数对照；非端到端","pageClass":"six-governance-article"},"headers":[],"relativePath":"zh/research/2026-11-18-mcp-parameter-knows-session.md","filePath":"zh/research/2026-11-18-mcp-parameter-knows-session.md","lastUpdated":1794982424000}'),i={name:"zh/research/2026-11-18-mcp-parameter-knows-session.md"};function p(g,e,h,m,u,_){const r=t("ArticleCover"),a=t("ArticleTableScroll");return n(),d("div",null,[o(r,{image:"/assets/mcp-session-boundary-20261118/mcp-session-boundary.cover.png",kicker:"工程研究 · 数据授权",title:"一个参数名，怎么会读到 AI 的会话资料？",summary:"服务端声明了一个字段名，客户端会不会因此交出同名会话数据？我们用两版 ADK 和 CodeFlowMu 的实际桥接做了对照。",version:"2026-11-18",languageHref:"/en/research/2026-11-18-mcp-parameter-knows-session",languageLabel:"English"}),o(a,{language:"zh"}),e[0]||(e[0]=c('<h1 id="一个参数名-怎么会读到-ai-的会话资料" tabindex="-1">一个参数名，怎么会读到 AI 的会话资料？ <a class="header-anchor" href="#一个参数名-怎么会读到-ai-的会话资料" aria-label="Permalink to &quot;一个参数名，怎么会读到 AI 的会话资料？&quot;">​</a></h1><p>你请 AI 助手从一个外部服务读取操作说明。这个服务列出自己需要的参数，其中一个名字叫“用户邮箱”。你并没有在这次请求里填写邮箱。<strong>光是服务端写下这个名字，客户端会不会自己从会话里找出邮箱发过去？</strong></p><p>这不是抽象的安全猜想。<a href="https://github.com/google/adk-python/commit/889ddd3134df1dd1a626205ee78811950dec2a5c" target="_blank" rel="noreferrer">Google ADK Python 的修复提交</a>指出，旧版 <code>McpInstructionProvider</code> 会先读取 MCP 服务声明的 prompt 参数名，再到本地 session state 找同名字符串，最后把值交给服务。新版改为：默认不附带参数；开发者需要明确给出要发送的 <code>arguments</code>。这是一项破坏兼容性的安全修正，<strong>提交本身没有宣称已发生生产环境泄漏</strong>。</p><h2 id="谁决定了请求里的内容" tabindex="-1">谁决定了请求里的内容？ <a class="header-anchor" href="#谁决定了请求里的内容" aria-label="Permalink to &quot;谁决定了请求里的内容？&quot;">​</a></h2><p>MCP 可以让外部服务提供 prompt、工具和资源。服务描述“我需要什么字段”很正常；问题出在客户端把这份描述当成了“你可以读取我会话状态里哪些字段”的决定。字段名本来只是格式，到了旧调用路径却变成了取值指令。</p><p>我们从修复前的父提交和修复提交分别抽取<strong>原样的提供者类</strong>，给它同一组替身数据：服务声明 <code>user:email</code> 和 <code>adk_oauth2_credential</code>，会话里放入合成邮箱与明显标注为假的凭证。替身 MCP 会话只记录收到什么，没有真实账号或网络调用。</p><table tabindex="0"><thead><tr><th>对照</th><th style="text-align:right;">服务发现次数</th><th>送到替身 <code>get_prompt</code> 的参数</th></tr></thead><tbody><tr><td>修复前，未显式给参数</td><td style="text-align:right;">1</td><td>合成邮箱和合成凭证</td></tr><tr><td>修复后，未显式给参数</td><td style="text-align:right;">0</td><td>无参数</td></tr><tr><td>修复后，明确只给 <code>locale</code></td><td style="text-align:right;">0</td><td>只有 <code>zh-CN</code></td></tr><tr><td>修复后，调用者明确取出合成凭证</td><td style="text-align:right;">0</td><td>仍会发送该合成值</td></tr></tbody></table><p>六项断言通过。最后一行很关键：修复取消了<strong>服务端借字段名隐式选择会话值</strong>的通道；它没有替开发者审查每一个主动填写的参数。</p><p><img src="'+l+'" alt="修复前后：参数声明与会话数据之间的边界"></p><h2 id="回头检查自己的多-agent-系统" tabindex="-1">回头检查自己的多 Agent 系统 <a class="header-anchor" href="#回头检查自己的多-agent-系统" aria-label="Permalink to &quot;回头检查自己的多 Agent 系统&quot;">​</a></h2><p>CodeFlowMu 是我们开发的本地多 Agent 协作系统。它允许 Codex Host 连接外部 MCP 服务，也有自己的正式协作工具。上游案例使我们追问：<strong>外部服务的 schema 里若也写了敏感字段名，我们的桥接会不会替它到任务或会话里取值？</strong></p><p>我们调用了 CodeFlowMu V3.0.152 的实际 <code>CodexMcpToolBridge</code>，用替身 app-server 声明同名敏感字段。发现工具时没有调用工具；传入空 <code>arguments</code> 就只转发空对象；只传 <code>locale</code> 就只转发 <code>locale</code>；显式传入合成凭证则照样转发。额外塞入 <code>session_state</code> 字段被拒绝，把外部调用指向保留给正式协作的 <code>fcop</code> 服务也被拒绝。七项断言通过。</p><p>另一条 Source 插件接入路径还允许通过<strong>明确的配置</strong>把环境变量交给插件进程。我们对实际环境构造函数做了三项断言：没配置的令牌不会凭空出现，配置的合成令牌会进入插件环境。这不是上游那个“服务只报字段名便取会话值”的机制，却提醒我们：<strong>修掉一种隐式流动，不等于所有数据流动都已获得恰当授权。</strong></p><h2 id="这轮能下什么结论" tabindex="-1">这轮能下什么结论？ <a class="header-anchor" href="#这轮能下什么结论" aria-label="Permalink to &quot;这轮能下什么结论？&quot;">​</a></h2><p>在已测的 CodeFlowMu Codex 外部 MCP 桥接中，<strong>没有复现 ADK 旧版的同名会话状态自动匹配</strong>。但替身 app-server 不等于真实模型、真实 MCP 传输或完整执行链；Source 传输也没有跑端到端。现有桥接单测因本地缺少 <code>@cursor/sdk</code> 在导入时停下，不能算通过。我们因此没有确认 CodeFlowMu 产品缺陷，本轮也没有开发评审项目。</p><p>真正值得继续研究的问题更具体：当一个模型<strong>主动</strong>把任务材料填进工具参数，或运维人员<strong>明确</strong>把凭证配置给插件时，系统该怎样证明这次数据提供符合当前任务授权？工具 schema 能说明字段格式，却不能独自回答“为什么这份资料可以交给这个服务”。</p><p>你也可以拿自己的一次 MCP 调用做个小检查：把服务声明的字段、实际发送的参数、参数来源并排放在一起。三栏若说不清楚，争论“它有没有权限”就还少了一段证据。<a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-18-mcp-arguments/00-report.en.md" target="_blank" rel="noreferrer">实验范围与逐项结果（English）</a>保留了固定版本和限制。</p>',17))])}const A=s(i,[["render",p]]);export{C as __pageData,A as default};
